**Please describe the purpose of this pull request.**
This PR enables `response_format: {"type": "json_object"}` aka JSON mode for all openai requests. This ensures that responses are going to come back in valid JSON. While it doesn't seem to be a problem with OpenAI, using openai compatible endpoints (aka open source models) can sometimes struggle to create well formed JSON without llama.cpp's grammar restrictions. 

Also enables Debug logging by setting the env var `LOG_LEVEL: DEBUG`, case sensitive. Still defaults to false.

**How to test**

Create a file called `request.json`:
```
{
  "model": "hermes-2-pro-theta-llama3",
  "response_format": {"type": "json_object"},
  "messages": [
    {
      "content": "What is the weather in boston, seattle, and san francisco?? respond in json",
      "role": "user"
    },
    {
      "content": "{\"status\": \"OK\", \"message\": null, \"time\": \"2024-05-20 05:42:30 PM UTC+0000\"}",
      "role": "tool",
      "tool_call_id": "e394f68c-d68b-4115-97e9-989a0"
    }
  ],
  "frequency_penalty": 0,
  "logprobs": false,
  "n": 1,
  "presence_penalty": 0,
  "response_format": {
    "type": "json_object"
  },
  "stream": false,
  "temperature": 1,
  "top_p": 1,
  "user": "00000000-0000-0000-0000-000000000000",
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "get_weather",
        "description": "Get the weather for a list of locations",
        "parameters": {
          "type": "object",
          "properties": {
            "locations": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "A list of locations (e.g., city names or zip codes)"
            },
            "unit": {
              "type": "string",
              "enum": ["celsius", "fahrenheit"]
            },
            "request_heartbeat": {
              "type": "boolean",
              "description": "Request an immediate heartbeat after function execution. Set to 'true' if you want to send a follow-up message or run a follow-up function."
            }
          },
          "required": [
            "locations",
            "request_heartbeat"
          ]
        }
      }
    }
  ],
  "tool_choice": "auto"
}
```

Run the following command:
```
curl $LOCALAI/v1/chat/completions   -H "Content-Type: application/json"  -d @request.json | jq
```

